var o=[{title:`Benefícios e autorização`,text:`A ACOG aconselha que muitas pessoas com gravidezes sem complicações podem continuar ou começar atividade aeróbica e de condicionamento de força adequada. Fale sobre o exercício com o seu profissional de saúde obstétrico, sobretudo se estiver a começar uma rotina nova ou tiver complicações. Ele pode dizer-lhe se a sua gravidez é medicamente descomplicada. O TrainUp não pode.`},{title:`Adapte-se à medida que as coisas mudam`,text:`O equilíbrio, a tolerância ao calor, o conforto respiratório e os movimentos que prefere podem mudar ao longo da gravidez. Escolha atividades confortáveis. Evite o sobreaquecimento, as atividades com risco real de quedas ou colisões e as posições que lhe causem tonturas. Se fazia muito exercício antes, pode manter alguma atividade exigente com orientação clínica, porque a gravidez não significa automaticamente repouso total.`},{title:`Sinais de alerta`,text:`Pare de fazer exercício e contacte o seu clínico obstétrico se tiver hemorragia vaginal, perda de líquido, dor no peito, tonturas, dor ou inchaço na barriga da perna, contrações dolorosas ou falta de ar invulgar. Os sintomas de emergência precisam de cuidados urgentes. Não tente contornar sintomas específicos da gravidez trocando de exercícios.`},{title:`Depois do parto`,text:`Quando pode voltar ao exercício depende do parto, da sua recuperação, dos sintomas do pavimento pélvico e de outros fatores pessoais. Caminhar com facilidade pode ser adequado para algumas pessoas. Dor persistente, perdas, sensação de peso ou outros problemas precisam de uma avaliação profissional, e nenhum prazo fixo serve a todas. O TrainUp não constrói programas para a gravidez, o pavimento pélvico ou o pós-operatório.`}];var i=[{label:`ACOG: exercício durante a gravidez`,url:`https://www.acog.org/womens-health/faqs/exercise-during-pregnancy`},{label:`ACOG: exercício durante a gravidez e no pós-parto`,url:`https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2020/04/physical-activity-and-exercise-during-pregnancy-and-the-postpartum-period`}];var r={sections:o,sources:i};export{r as default,o as sections,i as sources};